const repo = '/Users/buns/Documents/GitHub/OpenCoven/coven-cave/.worktrees/issue-5767-desktop-qualification';
const app = '/private/tmp/cave-5767-parallel-cargo-target/release/bundle/macos/CaveParallelQualification5767.app';
