      await phase('live-after-effects', { counter: 3, providerRequests: 1 });
      await control('finish');
      for (const [event, data] of base.afterRelease.slice(1)) frame(res, event, JSON.parse(JSON.stringify(data).replaceAll('{{COUNTER}}', '3')));
      res.end();
